SELECT d.id, d.dept_name, COUNT(e.id) AS employee_count, COUNT(DISTINCT e.salary) AS unique_job_titles, ROUND((100 * SUM(CASE WHEN e.job_title = 'Manager' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_manager FROM departments d LEFT OUTER JOIN employees e ON e.dept_id = d.id WHERE d.budget >= 2703000 GROUP BY d.id, d.dept_name HAVING employee_count >= 3 ORDER BY employee_count, id, dept_name LIMIT 50
